files.patch:
@@ -9941,0 +9941,5 @@
+// Convert condition code into -1,0,1, where
+// -1 means less
+//  0 means equal
+//  1 means greater.
+
@@ -9946,2 +9951,2 @@
-  ins_cost(DEFAULT_COST * 5 + BRANCH_COST);
-  size(24);
+  ins_cost(DEFAULT_COST * 4);
+  size(20);
@@ -9950,2 +9955,0 @@
-    Label done;
-    // compare registers
@@ -9953,20 +9956,33 @@
-    // Convert condition code into -1,0,1, where
-    // -1 means less
-    //  0 means equal
-    //  1 means greater.
-    if (VM_Version::has_LoadStoreConditional()) {
-      Register one       = Z_R0_scratch;
-      Register minus_one = Z_R1_scratch;
-      __ z_lghi(minus_one, -1);
-      __ z_lghi(one, 1);
-      __ z_lghi( $dst$$Register, 0);
-      __ z_locgr($dst$$Register, one,       Assembler::bcondHigh);
-      __ z_locgr($dst$$Register, minus_one, Assembler::bcondLow);
-    } else {
-      __ clear_reg($dst$$Register, true, false);
-      __ z_bre(done);
-      __ z_lhi($dst$$Register, 1);
-      __ z_brh(done);
-      __ z_lhi($dst$$Register, -1);
-    }
-    __ bind(done);
+    __ load_const_optimized($dst$$Register, 1);
+    __ load_on_condition_imm_32($dst$$Register, 0, Assembler::bcondEqual);
+    __ load_on_condition_imm_32($dst$$Register, -1, Assembler::bcondLow);
+  %}
+  ins_pipe(pipe_class_dummy);
+%}
+
+instruct cmpU3_reg_reg(iRegI dst, iRegI src1, iRegI src2, flagsReg cr)%{
+  match(Set dst (CmpU3 src1 src2));
+  effect(KILL cr);
+  ins_cost(DEFAULT_COST * 4);
+  size(18);
+  format %{ "cmpU3 $dst,$src1,$src2" %}
+  ins_encode %{
+    __ z_clr($src1$$Register, $src2$$Register);
+    __ load_const_optimized($dst$$Register, 1);
+    __ load_on_condition_imm_32($dst$$Register, 0, Assembler::bcondEqual);
+    __ load_on_condition_imm_32($dst$$Register, -1, Assembler::bcondLow);
+  %}
+  ins_pipe(pipe_class_dummy);
+%}
+
+instruct cmpUL3_reg_reg(iRegI dst, iRegL src1, iRegL src2, flagsReg cr)%{
+  match(Set dst (CmpUL3 src1 src2));
+  effect(KILL cr);
+  ins_cost(DEFAULT_COST * 4);
+  size(20);
+  format %{ "cmpUL3 $dst,$src1,$src2" %}
+  ins_encode %{
+    __ z_clgr($src1$$Register, $src2$$Register);
+    __ load_const_optimized($dst$$Register, 1);
+    __ load_on_condition_imm_32($dst$$Register, 0, Assembler::bcondEqual);
+    __ load_on_condition_imm_32($dst$$Register, -1, Assembler::bcondLow);
